// main.ts — entry point for make.fun news-image-20261124.
//
// Copies the already-committed entry.png to the output directory the
// harness expects. The image was generated by draw.py (Pillow) during
// the witnessed build and is committed in this repo; re-running draw.py
// at grade time is not possible — the grader sandbox has no Pillow —
// so this program never invokes Python. No network is used and repeated
// runs produce identical bytes.
//
// Usage:
//   MAKEFUN_OUTPUT_DIR=out node main.ts
// (defaults to /output when the variable is unset, matching the
// competition harness.)

import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = dirname(fileURLToPath(import.meta.url));
const source = join(repoRoot, "entry.png");
const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
const target = join(outDir, "entry.png");

function main(): void {
  if (!existsSync(source)) {
    throw new Error(`committed ${source} is missing`);
  }
  mkdirSync(outDir, { recursive: true });
  copyFileSync(source, target);
  const sourceBytes = statSync(source).size;
  const bytes = statSync(target).size;
  if (bytes !== sourceBytes) {
    throw new Error(
      `copied entry.png is ${bytes} bytes, expected ${sourceBytes}`
    );
  }
  if (bytes > 1048576) {
    throw new Error(`entry.png is ${bytes} bytes, over the 1 MiB limit`);
  }
  console.log(`entry.png -> ${target} (${bytes} bytes)`);
}

main();
